using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.ANM.TiposAnuncio{    [SwaggerSchema("Modelo de lectura de un TiposAnuncio")]    [GraphQLDescription("Objeto que representa un TiposAnuncio existente.")]    public class clReadTiposAnuncio    {        [SwaggerSchema("Identificador único del TiposAnuncio")]        [GraphQLDescription("Identificador único del TiposAnuncio")]        public int? TipoAnuncioID { get; set; }        [SwaggerSchema("TipoAnuncio")]        [GraphQLDescription("TipoAnuncio")]        public string? TipoAnuncio { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TiposAnuncio")]    [GraphQLDescription("Input para crear un TiposAnuncio.")]    public class clCreateTiposAnuncio    {        [GraphQLNonNullType] [SwaggerSchema("TipoAnuncio")]        [GraphQLDescription("TipoAnuncio")]        public string TipoAnuncio { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TiposAnuncio")]    [GraphQLDescription("Input para actualizar parcialmente un TiposAnuncio.")]    public class clUpdateTiposAnuncio    {        [SwaggerSchema("Identificador único del TiposAnuncio")]        [GraphQLDescription("Identificador único del TiposAnuncio")]        public int? TipoAnuncioID { get; set; }        [SwaggerSchema("TipoAnuncio")]        [GraphQLDescription("TipoAnuncio")]        public string? TipoAnuncio { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}